for (name, signature, explanation) in (
    (:user, "user(content)\n    user(first, second, rest...)", "Build a user Message from text, a prompt Part, or a sequence mixing them. Empty text is allowed; an empty sequence is not. No provider is contacted."),
    (:assistant, "assistant(content)\n    assistant(first, second, rest...)", "Build an assistant Message. Preserve returned messages and their continuation state when replaying real responses rather than reconstructing only their visible text."),
    (:developer, "developer(content)\n    developer(first, second, rest...)", "Build a developer-instruction Message from text and supported prompt parts. Provider mappings may translate the role."),
    (:text, "text(value::AbstractString)\n    text(message::Message)\n    text(answer::Response)", "For a string, construct TextPart. For Message, join text-only parts with newlines, or return nothing if any part is not text. For Response, allow accompanying thinking/citations but require at least one TextPart; tool calls, refusals and media make text(answer) return nothing. No content is silently flattened."),
    (:thinking, "thinking(text; continuation=())", "Construct ThinkingPart. This is a content factory, not a response accessor or a request to enable reasoning. Use Config(reasoning=Reasoning(...)) for generation control."),
    (:refusal, "refusal(text; continuation=())", "Construct a nonempty RefusalPart. Refusal is protocol content, not a tool result."),
    (:citation, "citation(; url=nothing, title=nothing, text=nothing, continuation=())", "Construct CitationPart with at least one present field. See citations for extracting citations from a Response."),
    (:image, "image(; data=nothing, url=nothing, file_id=nothing, path=nothing, media_type=nothing, detail=nothing, continuation=())", "Construct ImagePart from exactly one source. Raw UInt8 vectors are base64-encoded. Recognized path extensions suggest a MIME type without reading the file; explicit media_type wins. Unknown extensions use image/png."),
    (:audio, "audio(; data=nothing, url=nothing, file_id=nothing, path=nothing, media_type=nothing, continuation=())", "Construct AudioPart from exactly one source. Accept raw bytes via data; infer known path MIME extensions without opening the file, otherwise default to audio/wav."),
    (:video, "video(; data=nothing, url=nothing, file_id=nothing, path=nothing, media_type=nothing, continuation=())", "Construct VideoPart from exactly one source. Known path extensions infer MIME; the fallback is video/mp4. This does not generate video."),
    (:document, "document(; data=nothing, url=nothing, file_id=nothing, path=nothing, media_type=nothing, continuation=())", "Construct DocumentPart. Data bytes are encoded; path MIME inference is extension-based, with application/pdf as fallback. No OCR, upload or file reading occurs here."),
    (:binary, "binary(; data=nothing, url=nothing, file_id=nothing, path=nothing, media_type=nothing, continuation=())", "Construct BinaryPart, defaulting to application/octet-stream when no known path extension or explicit MIME applies. Provider support is required before sending it."),
    (:bytes, "bytes(part)\n    bytes(upload::FileUploadRequest)", "Decode inline media bytes or read a local path. URL and file-ID media must be fetched explicitly; this accessor does not perform network downloads. For an upload backed by bytes_data, return a copy. A path read can raise filesystem errors."),
    (:tool_call, "tool_call(id, name, input; continuation=())", "Construct ToolCallPart from a call ID, tool name and string-keyed JSON input object. This does not execute a function or validate the arguments against a tool schema."),
    (:tool_result, "tool_result(id, content; name=nothing, is_error=false, continuation=())\n    tool_result(call::ToolCallPart, content; is_error=false)", "Construct ToolResultPart from text or supported presentational parts. The call form preserves ID and name. Arbitrary numeric/record outputs need tool_content or execute_tool; the canonical content factory does not stringify arbitrary objects. is_error describes an application-chosen error result; exceptions are not automatically converted."),
    (:tool_message, "tool_message(results::ToolResultPart...)\n    tool_message(call::ToolCallPart, content; kwargs...)\n    tool_message(id::AbstractString, content; kwargs...)\n    tool_message(results::AbstractDict)", "Build a tool-role Message. The dictionary form maps call IDs to content through tool_result, retaining iteration order. Prefer the call form or already constructed results when the provider needs the function name."),
    (:parts_of, "parts_of(T, message::Message)\n    parts_of(T, answer::Response)", "Return a vector containing parts of type T, where T is a subtype of Part. The parts themselves are not deep-copied."),
    (:tool_calls, "tool_calls(answer::Response)", "Return the answer's ToolCallPart values as a vector. The result can be empty. Retrieval is local and performs no tool execution."),
    (:citations, "citations(answer::Response)", "Return CitationPart values from the assistant message. Empty when none are represented canonically."),
    (:continuation_data, "continuation_data(value, provider, kind)", "Find the first matching continuation state's data or return nothing. value is an object with a continuation field, or a tuple of states. The dictionary is shared; do not mutate replay state during requests."),
    (:parse_json, "parse_json(answer::Response)", "Parse a text-representable response as JSON. Throw if text(answer) is nothing or the text is invalid JSON. This does not validate against response_format's schema. Parsed integers retain BigInt precision; tool_arguments converts them to selected Julia argument types."),
    (:kind, "kind(part_or_delta_or_event_or_tool)", "Return the canonical string discriminator, such as text, tool_call, delta or turn_end. Not every canonical object has a discriminator; Request and Response do not."),
    (:validate, "validate(value)", "Validate an existing canonical value or supported policy and return it unchanged. Constructors also validate. Invalid shapes, enum values, ranges, content combinations or non-JSON opaque values raise ArgumentError. Validity does not imply provider support."),
    (:to_dict, "to_dict(value; include_provider_data=false)", "Serialize a canonical value to a string-keyed object. Optional fields are omitted by their typed rules; opaque dictionaries are not cleaned or deep-copied. Response.provider_data is excluded unless requested when serializing a Response directly; nested responses in BatchEntry include it. This omission flag is not a general redaction policy. Credential serialization exposes secrets: do not log it."),
    (:to_json, "to_json(value; include_provider_data=false)", "Serialize a canonical value to JSON text using to_dict's rules. This is not a generic Julia-object serializer: use tool_content for ordinary tool outputs. Opaque provider/replay data and credentials can be sensitive."),
    (:from_dict, "from_dict(T, object)\n    from_dict(kind::AbstractString, object)", "Read a canonical type or serialization-kind name from a string-keyed object. Variant tags select concrete parts/events. Contract-defined leniency applies to incoming provider-like data, while typed counters and caller-authored constructors remain checked. Unknown fields are not an instruction to execute code."),
    (:from_json, "from_json(T, json::AbstractString)", "Parse JSON then construct the requested canonical type through from_dict. Invalid JSON or invalid typed fields raise an error. This reads data only and does not submit a request."),
)
    doc = "    " * signature * "\n\n" * explanation
    @eval @doc $doc $name
end
